  assert.equal(r4.status, 0, r4.stderr);
  const result4 = readJson(out4);
  assert.ok(result4.welch.p_value <= 0.5);
  // 2% 未达默认 5% 阈值
  assert.equal(result4.decision, 'no_material_change');
});

test('归因平手按 central_tendency > tail_latency > variability 顺序', () => {
