  return t >= 0 ? 1 - ib / 2 : ib / 2;
}

// t 分布分位数（调用方保证 0.5 < p < 1、df > 0）：
// 对单调递增的 tCdf 做定长二分，结果确定。
function tQuantile(p, df) {
  let lo = 0;
  let hi = 1;
  while (tCdf(hi, df) < p) {
    hi *= 2;
  }
  for (let i = 0; i < 100; i++) {
    const mid = (lo + hi) / 2;
    if (tCdf(mid, df) < p) {
      lo = mid;
    } else {
      hi = mid;
    }
  }
  return (lo + hi) / 2;
}

// 候选均值减基线均值的双侧 Welch 置信区间（置信水平 1 - alpha），
// 返回未舍入的 [lower, upper]。退化情形与 welchTest 对齐：
// 两侧方差均为 0 时，均值相同为 [0, 0]，不同为 [m2 - m1, m2 - m1]。
function welchConfidenceInterval(baseline, candidate, alpha) {
  const n1 = baseline.length;
  const n2 = candidate.length;
  const m1 = meanOf(baseline);
  const m2 = meanOf(candidate);
  const v1 = sampleVariance(baseline, m1);
  const v2 = sampleVariance(candidate, m2);

  if (v1 === 0 && v2 === 0) {
    const diff = m1 === m2 ? 0 : m2 - m1;
    return [diff, diff];
  }

  const s1 = v1 / n1;
  const s2 = v2 / n2;
  const df = (s1 + s2) ** 2 / (s1 ** 2 / (n1 - 1) + s2 ** 2 / (n2 - 1));
  const tCrit = tQuantile(1 - alpha / 2, df);
  const halfWidth = tCrit * Math.sqrt(s1 + s2);
  return [m2 - m1 - halfWidth, m2 - m1 + halfWidth];
}

module.exports = { computeSummary, round6, welchTest, welchConfidenceInterval };

