  }
  if (report.unit !== 'ns') {
    return { error: `${label} 文件 unit 必须为 "ns"` };
  }
  if (typeof report.command !== 'string') {
    return { error: `${label} 文件缺少有效的 command 字段` };
  }
  if (!Array.isArray(report.samples)) {
    return { error: `${label} 文件 samples 必须为数组` };
  }
