  const baseline = [100, 102, 98, 101, 99];
  const candidate = [120, 122, 118, 121, 119];
  const w = welchTest(baseline, candidate);
  const [lower, upper] = welchConfidenceInterval(baseline, candidate, 0.05);
  const halfWidth = (upper - lower) / 2;
